import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss; // Positive for profit, negative for loss

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

Map<String, double> calculateAverageProfitLoss(List<Transaction> transactions) {
  final profitMap = <String, double>{};
  final lossMap = <String, double>{};

  for (final transaction in transactions) {
    profitMap.update(transaction.coinName, (value) => value + transaction.profitLoss,
        ifAbsent: () => transaction.profitLoss);
    lossMap.update(transaction.coinName, (value) => value + transaction.profitLoss,
        ifAbsent: () => transaction.profitLoss); // Utilize same logic for loss tracking
  }

  // Calculate averages and rank
  final sortedProfits = profitMap.entries.map((entry) => MapEntry(entry.key, entry.value / transactions.where((t) => t.coinName == entry.key).length)).toList()
    ..sort((a, b) => b.value.compareTo(a.value)); // Descending order by average profit
  final sortedLosses = lossMap.entries.map((entry) => MapEntry(entry.key, entry.value / transactions.where((t) => t.coinName == entry.key).length))
    ..sort((a, b) => a.value.compareTo(b.value)); // Ascending order by average loss

  return {
    'topProfits': Map.fromEntries(sortedProfits.sublist(0, 3)),
    'topLosses': Map.fromEntries(sortedLosses.sublist(0, 3))
  };
}

void main() {
  // Example Usage (Populate your transaction list here with actual data)
  List<Transaction> transactions = [
    Transaction("BTC", DateTime.now().subtract(Duration(days: 10)), 500.0),
    Transaction("ETH", DateTime.now().subtract(Duration(days: 7)), -250.5),
    Transaction("LTC", DateTime.now().subtract(Duration(days: 5)), 120.8),

```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction({required this.coinName, required this.dateTime, required this.profitLoss});
}

Map<String, double> calculateAverageProfitLoss(List<Transaction> transactions) {
  // Group transactions by coin name and compute average profit/loss for each
  final Map<String, List<double>> coinProfits = transactions.groupBy((t) => t.coinName)
      .map((coin, list) => MapEntry(coin, list.map((t) => t.profitLoss).toList()));

  final Map<String, double> averages = {};
  for (var entry in coinProfits.entries) {
    double sum = entry.value.reduce((a, b) => a + b);
    averages[entry.key] = sum / entry.value.length;
  }

  // Extract top 3 highest and lowest averages
  final sortedProfits = averages.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value)); // Descending order by profit
  final top3Profits = sortedProfits.sublist(0, 3).map((e) => e.key);
  final sortedLosses = averages.entries.toList()
    ..sort((a, b) => a.value.compareTo(b.value)); // Ascending order by loss (negative profit)
  final top3Losses = sortedLosses.sublist(0, 3).map((e) => e.key);

  return {
    'topProfits': top3Profits,
    'topLosses': top3Losses,
  };
}

void main() {
  // Example usage (replace with your actual transaction data)
  List<Transaction> transactions = [
    Transaction(coinName: 'BTC', dateTime: DateTime.now(), profitLoss: 150.5),
    Transaction(coinName: 'ETH', dateTime: DateTime.now().subtract(Duration(days: 2)), profitLoss: -25.3),
    Transaction(coinName: 'LTC', dateTime: DateTime.now().subtract(Duration(days: 1)), profitLoss: 87.

```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction({required this.coinName, required this.dateTime, required this.profitLoss});
}

Future<Map<String, dynamic>> analyzeTopCoins(List<Transaction> transactions) async {
  // Group transactions by coin name for aggregation
  final groupedTransactions = transactions.groupBy((t) => t.coinName);

  // Calculate average profit/loss per coin
  final avgProfits = <String, double>{};
  final avgLosses = <String, double>{};
  for (var (coin, coinTransactions) in groupedTransactions.entries) {
    double totalProfit = 0;
    double totalLoss = 0;
    for (var transaction in coinTransactions) {
      totalProfit += transaction.profitLoss > 0 ? transaction.profitLoss : 0;
      totalLoss += transaction.profitLoss < 0 ? -transaction.profitLoss : 0;
    }
    avgProfits[coin] = totalProfit / coinTransactions.length;
    avgLosses[coin] = totalLoss / coinTransactions.length;
  }

  // Extract top 3 with highest average profit and loss
  final topProfits = avgProfits.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value))
    ..sublist(0, 3)
    .map((entry) => {'coin': entry.key, 'averageProfit': entry.value})
    .toList();

  final topLosses = avgLosses.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value))
    ..sublist(0, 3)
    .map((entry) => {'coin': entry.key, 'averageLoss': entry.value})
    .toList();

  return {
    'topProfits': topProfits,
    'topLosses': topLosses,
  };
}
```

