     ```typescript
     import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
     import { Document } from 'mongoose';

     export type ProductDocument = Product & Document;

     @Schema({ timestamps: true }) // Optional: Add createdAt, updatedAt fields
     export class Product {
         @Prop({ required: true })
         name: string;

         @Prop({ unique: true })
         sku: string;

         // Embedded Schema for 'Reviews'
         @Schema({ _id: false }) // Reviews won't have their own IDs
         reviews: Review[]; 
     }

     export interface Review {
         @Prop({ required: true })
         rating: number;
         @Prop()
         comment: string;
         @Prop()
         author: string; // Example additional field
     }

     export const ProductSchema = SchemaFactory.createForClass(Product);
     ```

     - **Explanation:**
       - `Product` is our main schema.
       - `reviews`: An array of `Review` objects, *embedded* within `Product`. Notice `_id: false` to prevent Reviews getting independent IDs.
