using namespace std;

// Recursive Fibonacci function with error handling
int fibonacci(int a, int b, int n) {
    if (n <= 0) {
        cerr << "Error: Invalid sequence length (must be positive)." << endl;
        return -1; // Signal error
    } else if (n == 1) {
        return a;
    } else if (n == 2) {
        return b;
    } else {
        return fibonacci(b, a + b, n - 1);
    }
}

// Function to generate and print the Fibonacci sequence
void generateFibonacci(int start1, int start2, int count) {
    if (!isdigit(tolower(cin.peek()))) {  // Initial input validation
        cerr << "Error: Invalid input detected. Please enter integers only." << endl;
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        return; // Exit gracefully on invalid initial input
    }

    int seq[count];
    seq[0] = start1;
    seq[1] = start2;

    cout << seq[0] << ", ";  // Output the first element

    for (int i = 2; i < count; ++i) {
        seq[i] = fibonacci(seq[i - 1], seq[i - 2], i + 1); // Recursive call with error check
        if (seq[i] == -1) {  // Handle recursion errors
            cerr << "Internal Error: Fibonacci calculation failed." << endl;
            return;
        }
        cout << seq[i] << ", ";
    }
    cout << endl; // Endline for cleaner output
}

