import Foundation

func correctHomophones(input: String) -> String {
    let homophoneMap: [String: String] = [
        "their": "there",
        "know": "no",
        "weigh": "way",
        "too": "to",
        "yew": "you",
        "sea": "see",
        "sumthing": "something",
        "seams": "seems",
        "bee": "be",
        "eye": "I",
        "knot": "not",
        "right": "write",
        "butt": "but",
        "don't no": "do not know", // Handle phrasal homophones
        "write weigh": "right way", // Handle phrasal homophones
        "there/their/they're":  { context in  // Dynamic correction for trio
            switch context {
            case "there": return "there"
            case "their": return "their"
            case "they're": return "they're"
            default: return "**UNCATEGORIZED - THEY'RE GROUP**" // Flag for improvement
            }
        }
    ]

    var correctedText = input
    for (homophone, replacement) in homophoneMap {
        if let replacementClosure = replacement as? (String) -> String {
            correctedText = correctedText.replacingOccurrences(of: homophone, with: replacementClosure(extractContext(from: correctedText, around: homophone)))
        } else {
            correctedText = correctedText.replacingOccurrences(of: homophone, with: replacement)
        }
    }
    return correctedText
}

// Helper to extract context for dynamic replacements (improvements needed for robustness)
func extractContext(from text: String, around target: String) -> String {
    let range = text.range(of: target)!
    let before = text[..<range.lowerBound].last ?? "" // Simplified context capture, refine for accuracy
    let after = text[range.upperBound...].prefix(10) //  Limit context length, adapt as needed
    return "\(before)\(target)\(after)" // Combine for context
}

