import Foundation

func generateWinterSportAnalysis(sportPreference: String) -> [[String: String]] {
    var analysisData: [[String: String]] = [] // Our Excel-compatible data structure

    let factors: [String] = ["Speed", "Difficulty", "Style", "Learning Curve", "Terrain Variety", "Trick Opportunities"]
    let skiingStrengths = ["High", "Moderate (varies by technique)", "Classic & Controlled", "Relatively Steep Initially", "Excellent (all slopes)", "Limited but progressing"]
    let snowboardingStrengths = ["Moderate-High", "Steeper initial learning", "Expressive & Free-flowing", "Initially steeper, but rewarding progression", "Versatile (parks to backcountry)", "Extensive"]

    // Conditional Population based on User Input
    var factorValues: [String] 
    switch sportPreference.lowercased() {
    case "skiing":
        factorValues = skiingStrengths
    case "snowboarding":
        factorValues = snowboardingStrengths
    default:
        factorValues = ["N/A", "N/A", "N/A", "N/A", "N/A", "N/A"] // Handle unexpected input gracefully
    }

    // Constructing Excel-like Rows
    for (index, factor) in factors.enumerated() {
        let row: [String: String] = [factor: factorValues[index]]
        analysisData.append(row)
    }

    return analysisData
}

