import Foundation

func generateSportComparison(sportPreference: String) -> String { // Simulates Excel-ready data

    var comparisonData = """
    Winter Sport Comparison (Based on \(sportPreference))

    | Factor       | Skiing                     | Snowboarding                |
    |--------------|---------------------------|----------------------------|
    | Speed         | **High**                   | Moderate to High (Variable) |
    | Difficulty   | Gradual, Technique-focused | Steeper Initial Learning Curve |
    | Style        | Classic, Elegant          | Freestyle, Edgy, Dynamic     |
    | Learning Curve| Relatively Easier Initially | More Challenging Start     |
    | Terrain Variety| **Excellent**               | Adaptable, Park Emphasis   |
    | Trick Opportunities| Limited (Freestyle Skiing Exists) | **Extensive**              |
    """

    // Dynamic Adaptation using Conditional Formatting (Swift-style)

    if sportPreference.lowercased() == "skiing" {
        comparisonData = comparisonData.replacingOccurrences(of: "**High**", with: "**Emphasis**", in: comparisonData.components(separatedBy: "\n").last!, options: .caseInsensitive)
        comparisonData = comparisonData.replacingOccurrences(of: "Excellent", with: "**Emphasis**", options: .caseInsensitive) 
    } else if sportPreference.lowercased() == "snowboarding" {
        comparisonData = comparisonData.replacingOccurrences(of: "Moderate to High (Variable)", with: "**Emphasis**", options: .caseInsensitive)
        comparisonData = comparisonData.replacingOccurrences(of: "Extensive", with: "**Emphasis**", options: .caseInsensitive)
    }

    return comparisonData
}

