  if (inputData.sourceIP && inputData.destinationIP && inputData.sourceIP.match(/^[0-9a-fA-F]{8}:[0-9a-fA-F]{4}:[0-9a-fA-F]{4}:[0-9a-fA-F]{4}:[0-9a-fA-F]{4}:[0-9a-fA-F]{4}:[0-9a-fA-F]{4}:[0-9a-fA-F]{4}$/) &&  // IPv6 address pattern check
      inputData.port === 80) { 
    // Strong indicator for HTTP (commonly uses port 80 with IPv6)
    return "HTTP"; 
  } else if (inputData.sourceIP && inputData.destinationIP && inputData.port > 1023 &&  // UDP often uses higher ports
             inputData.payload &&  inputData.payload.length !== undefined) { 
    //  Payload suggests data transfer, leaning towards UDP
    return "UDP"; 
  } else { 
    // Default to IPv6  given the presence of a formatted IPv6 address
    return "IPv6"; 
  }
}

// Test with provided input:
const result = determineMostRelevantProtocol(inputData);
console.log(`Most relevant protocol based on input: ${result}`); // Output: HTTP 
```

