import { Injectable } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { Reflector } from '@nestjs/core';
import { User } from './user.entity'; // Assuming User entity handles roles
import { Roles } from './roles.decorator'; // Custom decorator for role checks

@Injectable()
export class RolesGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector) { super(); }

  canActivate(context: ExecutionContext): boolean | Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // No roles specified, allow access

    const user = context.switchToHttp().getRequest().user as User;
    return user && user.roles.some(role => requiredRoles.includes(role));
  }
}

