function geocodeAndStore(spreadsheetId, sheetName, placeColumnName, latColumn, lngColumn) {
  // 1. Access Spreadsheet and Sheet
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);

  // 2. Fetch Place Names and Process Rows
  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();
  for (let row = 1; row < values.length; row++) {  // Skip header row (assuming it's row 1)
    const placeName = values[row][placeColumnName - 1]; // Adjust column index as needed

    if (placeName) {  // Only geocode if a place name exists
      // 3. Geocoding using Places API (Google Maps Platform Required)
      const geocoder = new google.maps.Geocoder();
      geocoder.geocode({ address: placeName }, (results, status) => {
        if (status === google.maps.GeocoderStatus.OK) {
          const latitude = results[0].geometry.location.lat();
          const longitude = results[0].geometry.location.lng();

          // 4. Update Spreadsheet with Lat/Long
          sheet.getRange(row + 1, latColumn).setValue(latitude);  // +1 for row offset
          sheet.getRange(row + 1, lngColumn).setValue(longitude);
        } else {
          Logger.log(`Geocoding failed for ${placeName}: ${status}`); // Handle errors
        }
      });
    }
  }
}
```

