/**
 * Searches for a place name in a specified column and retrieves latitude and longitude, storing them in designated columns.
 *
 * @param {string} sheetName The name of the Google Sheet containing the data.
 * @param {number} placeColumnName The index (A=1, B=2, etc.) of the column with place names.
 * @param {number} latColumn  The index where latitudes will be stored.
 * @param {number} lngColumn  The index where longitudes will be stored.
 * @param {string} apiKey Your Google Maps Geocoding API key (obtain from https://developers.google.com/maps/documentation/geocoding/get-api-key)
 */
function geocodePlaces(sheetName, placeColumnName, latColumn, lngColumn, apiKey) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);
  const lastRow = sheet.getLastRow(); 

  // Iterate through each row containing a place name
  for (let row = 2; row <= lastRow; row++) { // Start from row 2, assuming header row is row 1
    const placeName = sheet.getRange(row, placeColumnName).getValue();
    if (placeName) {  // Only proceed if there's a place name
      const geocoder = new google.maps.Geocoder();
      geocoder.geocode({ address: placeName }, (results, status) => {
        if (status === 'OK' && results.length > 0) {
          const latitude = results[0].geometry.location.lat();
          const longitude = results[0].geometry.location.lng();
          sheet.getRange(row, latColumn).setValue(latitude);
          sheet.getRange(row, lngColumn).setValue(longitude);
          Logger.log(`Geocoded "${placeName}" - Lat: ${latitude}, Lng: ${longitude}`);
        } else {
          Logger.log(`Error geocoding "${placeName}": ${status}`);
          // Handle geocoding failures (e.g.,  display an error message in a separate column)
        }
      });
    }
  }
}
```

