<?php

function smart_sort_array(array $set, string $order = 'ASC'): array {
    /**
     * Sorts an array of associative arrays (with "name", "address", "age" keys) based on the "age" value.
     *
     * @param array $set The input array of sub-arrays.
     * @param string $order Sorting order ('ASC' for ascending, 'DESC' for descending, default: 'ASC').
     * @return array The sorted array.
     */
    usort($set, function($a, $b) use ($order) {
        $comparison = ($order === 'ASC') ? $a['age'] - $b['age'] : $b['age'] - $a['age']; 
        return $comparison; // Returns negative for $a < $b, positive for $a > $b, zero for equality
    });
    return $set;
}

// Example Usage:
$data = [
    ['name' => 'Alice', 'address' => '123 Main', 'age' => 25],
