const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius'); // Default to Celsius

  // Conversion functions (helper for verbosity)
  const celsiusToFahrenheit = (celsius) => (celsius * 9) / 5 + 32;
  const fahrenheitToCelsius = (fahrenheit) => (fahrenheit - 32) * 5 / 9;

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value));
  };

  const handleUnitChange = (event) => {
    setUnit(event.target.value);
  };

  // Calculate converted temperature based on selected unit
  let convertedTemp;
  if (unit === 'celsius') {
    convertedTemp = celsiusToFahrenheit(temperature);
  } else {
    convertedTemp = fahrenheitToCelsius(temperature);
  }

  return (
    <div>
      <h2>Temperature Converter</h2>
      <input
        type="number"
        value={temperature}
        onChange={handleInputChange}
        placeholder="Enter temperature"
      />
      <select value={unit} onChange={handleUnitChange}>
