<!DOCTYPE html>
<html>
<head>
  <title>Desktop Background Viewer</title>
  <style>
    #backgroundImageContainer {
      width: 500px; /* Adjust as needed */
      height: 300px; /* Adjust as needed */
      background-size: cover;
      display: none; /* Initially hidden */
    }
  </style>
</head>
<body>

  <h1>Display Your Desktop Background</h1>

  <button id="showDesktopBG">Show Background</button>
  <div id="backgroundImageContainer"></div>

  <script>
    const showDesktopBGButton = document.getElementById('showDesktopBG');
    const backgroundContainer = document.getElementById('backgroundImageContainer');

    showDesktopBGButton.addEventListener('click', async () => {
      try {
        // **Cross-browser approach using File System Access API (more modern and secure)**
        const desktopPath = await window.showDirectoryPicker({
          mode: 'openFile', // Allow selecting a single file (desktop wallpaper)
          types: [{description: 'Images', accept: {mimeTypes: ['image/*']}}] 
        });
        if (desktopPath) {
          const desktopBG = await fetch(desktopPath);
          const imgBlob = await desktopBG.blob();
          const imageUrl = URL.createObjectURL(imgBlob); 
          backgroundContainer.style.display = 'block';  
          backgroundContainer.style.backgroundImage = `url(${imageUrl})`;
        } else {
          console.log("User canceled selection.");
        }
      } catch (error) {
        console.error("Error accessing desktop: ", error);
        // Handle errors gracefully (e.g., display a fallback message)
      }
    });
  </script>

</body>
</html>
```

