public class ClimateChangeSummary
{
    public static void Main(string[] args)
    {
        // Summarize IPCC AR6 Key Findings (Weighted for Clarity & Detail)
        var summary = new Dictionary<string, string>
        {
            { "Human Influence", "Overwhelming scientific consensus: Human activities (primarily greenhouse gas emissions) are unequivocally driving current climate change." },
            { "Global Temperatures", "Significant warming observed globally, exceeding pre-industrial levels with unprecedented rate, leading to intensified heatwaves." },
            { "Sea Level Rise", "Accelerated sea level rise due to melting ice sheets and thermal expansion of oceans, threatening coastal communities." },
            { "Biodiversity Loss", "Widespread species extinction and ecosystem disruption directly linked to climate change impacts." },
            { "Urgency & Action", "Dire warning: Without drastic emission reductions and adaptation measures, severe and irreversible damage to society is imminent." }
        };

        Console.WriteLine("**IPCC AR6 Core Takeaways:**");
        foreach (var item in summary)
        {
            Console.WriteLine($"- {item.Key}: {item.Value}"); 
        }
        Console.WriteLine("\n**Implication:** Immediate, substantial global action is critical to mitigate climate change and secure a sustainable future.");
    }
}
```

