using Newtonsoft.Json; // Ensure you have Newtonsoft.Json NuGet package installed

public class ImmigrationData
{
    public int VisasIssued { get; set; }
    public Dictionary<string, int> TopCountries { get; set; }
    public PolicyChange[] PolicyChanges { get; set; }
}

public class PolicyChange
{
    public string date { get; set; }
    public string description { get; set; }
}

public class DataExtractor
{
    public static void AnalyzeImmigrationData(string jsonDataset)
    {
        // 1. Deserialize JSON into C# objects
        var data = JsonConvert.DeserializeObject<ImmigrationData>(jsonDataset);

        // 2. Extract Required Information:
        Console.WriteLine($"Visas Issued in 2021: {data.VisasIssued}");

        // Top Countries (sorted by count in descending order)
        var sortedTopCountries = data.TopCountries.OrderByDescending(x => x.Value).Take(3).ToList(); // Get top 3
        Console.WriteLine("\nTop Immigrant Countries (Top 3):");
        foreach (var country in sortedTopCountries)
            Console.WriteLine($"{country.Key}: {country.Value}");

        // Recent Policy Changes (focus on recency - adaptable for stricter criteria if needed)
        Console.WriteLine("\nRecent Policy Changes:");
        foreach (var change in data.PolicyChanges.OrderByDescending(p => p.date))
            Console.WriteLine($"- {change.date}: {change.description}");
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        string jsonData = @"{ ... your provided JSON ... }"; // Replace with actual JSON string
        DataExtractor.AnalyzeImmigrationData(jsonData);
    }
}
```

