#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *argvToCString(int argc, char **argv) {
    // Calculate total string length (including null terminators)
    size_t totalLength = 1; // Account for initial null terminator
    for (int i = 0; i < argc; ++i) {
        totalLength += strlen(argv[i]) + 1; // Add each argument's length + separator space
    }

    // Allocate memory for the concatenated string
    char *result = malloc(totalLength);
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(1); // Handle allocation error
    }

    char *currentPos = result;
    for (int i = 0; i < argc; ++i) {
        strcpy(currentPos, argv[i]);  // Copy each argument
        currentPos += strlen(argv[i]);
        *currentPos++ = ' '; // Add separator space
    }
    *(currentPos - 1) = '\0'; // Final null terminator

    return result;
}

int main(int argc, char **argv) {
    char *combinedString = argvToCString(argc, argv);
    printf("Combined string from argv: %s\n", combinedString);
    free(combinedString); // Remember to deallocate!
    return 0;
}
```

