```typescript
import { Injectable, NestMiddleware } from '@nestjs/common';

interface EnvCheckOptions {
  envVariable: string;
  proceedOn: boolean; // True to call next() when env matches, false otherwise
}

const envCheckDecorator = (options: EnvCheckOptions): MethodDecorator => {
  return (target: any, propertyKey: string, descriptor: PropertyDescriptor) => {
    const originalMethod = descriptor.value;

    descriptor.value = async (req, res, next) => {
      const envValue = process.env[options.envVariable];
      if (envValue === (options.proceedOn ? 'true' : 'false')) {
        return originalMethod.call(target, req, res, next); // Call next() or proceed
      } else {
        // Return false to halt execution flow
        return false; 
      }
    };
  };
};

@Injectable()
export class EnvConditionalMiddleware implements NestMiddleware {
  use(envCheck: typeof envCheckDecorator) = envCheck({ envVariable: 'NODE_ENV', proceedOn: true }); // Default: proceed on 'true' NODE_ENV

  // Example usage with decorator:
  @UseMiddleware(envCheck({ envVariable: 'DEBUG_MODE', proceedOn: false })) // Only execute in non-debug mode
  async myProtectedRouteHandler(req, res, next) {
    // ... your protected route logic ...
  }
}
```

**Explanation and Weighted Rating Justification:**

1. **Flexibility (Verbosity & Helpfulness):**
   - **`envCheckDecorator`:** This factory function creates customizable decorators based on `envVariable` and `proceedOn` logic. Users specify *exactly* how they want middleware behavior tied to the environment variable. High verbosity for clarity.
   - **Options Object:**  Makes the decorator adaptable to various scenarios (e.g., different env vars, reversing the "proceed" condition).

2. **Robust Implementation (Helpfulness):**
   - **Direct `process.env` Access:**  Properly retrieves the environment variable value for runtime decision-making.
   - **Clear Control Flow:**  Explicitly returns `false` to stop execution when the condition isn't met, ensuring middleware doesn't unintentionally call `next()` in undesired cases.
