       default = "react-django-sg"
     }

     # ... (Define additional variables for load balancers, etc. as needed)
     ```

   * **EC2 Instance:** Create a dynamic EC2 instance using variables:

     ```terraform
     resource "aws_instance" "webserver" {
       ami                         = "YOUR_AMIs_WITH_PYTHON_AND_DOCKER  (See Step 2)"
       instance_type                = var.instance_type
       key_name                     = var.key_pair_name
       subnet_id                    = "subnet_id_in_your_VPC"  
       tags = {
         Name = "react-django-app"
       }
       # Security Group (defined later for fine-grained control)
       security_groups = [var.security_group_name]
     }
