import React, { useState, useEffect } from 'react';
import { Combobox, Input, Transition } from 'downshift';
import { searchEmails } from './emailService'; // Assuming your async function is here

const EmailAutocomplete = () => {
  const [emails, setEmails] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
    // Trigger email search on input change with debounce for performance
    searchEmails(event.target.value)
      .then(results => setEmails(results))
      .catch(error => console.error('Email search error:', error)); 
  };

  return (
    <div>
      <Combobox
        itemToString={(email) => email} // String representation for display
        onChange={setInputValue} // Update input value on selection
        value={inputValue}
      >
        <Input
          placeholder="Enter email address..."
          onChange={handleInputChange}
          className="email-input" // Add custom styling as needed
        />
        <Transition show={emails.length > 0}>
          {(props) => (
            <ul {...props} className="dropdown-menu">
              {emails.map((email) => (
                <li key={email} onClick={() => setInputValue(email)}>
                  {email}
                </li>
              ))}
            </ul>
          )}
        </Transition>
      </Combobox>
    </div>
  );
};

export default EmailAutocomplete;
```

