export default function Library({ setInputMessage }: { setInputMessage: Dispatch }) {
  const utils = api.useContext();
  const [editedName, setEditedName] = useState("");
  const [editedPrompt, setEditedPrompt] = useState("");
  const [selectedTargetPrompt, setSelectedTargetPrompt] = useState(null); // Store ID for clarity

  // Combine queries and mutations for efficiency
  const { data: prompts, refetch: refreshPrompts } = api.prompt.all.useQuery();
  const { isOpen, onOpen, onClose } = useDisclosure();
  const mutationHandlers = {
    upsert: api.prompt.upsert.useMutation({
      onSuccess: async () => {
        await refreshPrompts(); // Refetch after upsert for updates
        utils.prompt.invalidate(); 
      },
    }),
    delete: api.prompt.delete.useMutation({
      onSuccess: async () => {
        await refreshPrompts(); // Refetch after deletion
        utils.prompt.invalidate();
      },
    }),
  };

  //  Efficient Rendering & Logic:
  return (
    <>
      <button 
        variant="ghost" 
        alignSelf={"flex-end"} 
        onClick={() => {
          setSelectedTargetPrompt(null); // Clear selection for new prompt
          setEditedName("");
          setEditedPrompt("");
          onOpen();
        }}
      >
        New Prompt
      </button>

      {/*  Sort and Map with Combined Logic */}
      <ul style={{ listStyle: "none", padding: 0, gap: 2 }}>
        {prompts?.sort((a, b) => b.updatedAt.getTime() - a.updatedAt.getTime())
          .map((p) => (
