              <button 
                variant="ghost" 
                alignSelf={"flex-end"} 
                onClick={() => {
                  setSelectedTargetPrompt(p.id);
                  setEditedName(p.name);
                  setEditedPrompt(p.prompt);
                  onOpen();
                }}
              >
                {p.name} - {p.prompt.substring(0, 30)}...{/* truncate for brevity */}
              </button>
            </li>
          ))}

