import Foundation

func optimisticGratitudeRearrangement(phrase: String) -> String {
    // 1. **Sentiment Infusion:**  Begin by extracting positive keywords (predefined set or learned model)  relevant to optimism and gratitude like "hope," "joy," "bless," etc.  Introduce these strategically within the rearranged structure.  This adds a direct thematic layer.

    // 2. **Adaptive Sorting with Emphasis:**  
    let impactfulLetters = phrase.filter { !$0.isWhitespace }.sorted() // Alphabetic base sort
    var emphasizedLetters = [String]()
    for letter in impactfulLetters {
        if ["a", "g", "i", "o", "t", "u"].contains(letter.lowercased()) { // Prioritize vowels and commonly used in positivity
            emphasizedLetters.insert(letter, at: 0) //  Place more frequently in optimistic contexts at the front
        } else {
            emphasizedLetters.append(letter)
        }
    }

    // 3. **Construction with Gratitude Phrase:**
    let gratitudeCore = "thankful for the" //  Fixed gratitude element
    let rearranged = "\(gratitudeCore) \(String(emphasizedLetters))!"

    return  "Embrace life with \(rearranged), cultivating joy and abundance." //  Enclosing sentence for impact
}

