import java.time.Duration;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;

public class PreciseDateDurationCalculator {

    public static void main(String[] args) {
        // Input Dates with Explicit Time Zones (example using ISO format for clarity)
        LocalDateTime startDateTime = LocalDateTime.parse("2022-01-01T10:00:00", DateTimeFormatter.ISO_LOCAL_DATE_TIME)
                .atZone(ZoneId.of("Europe/London")); 
        LocalDateTime endDateTime = LocalDateTime.parse("2022-01-01T15:30:00", DateTimeFormatter.ISO_LOCAL_DATE_TIME)
                .atZone(ZoneId.of("America/New_York"));

        // Calculate Duration, Accounting for Time Zones
        Duration duration = Duration.between(startDateTime, endDateTime);

        System.out.println("Duration (considering time zones): " + duration);
        System.out.println("Duration in hours: " + duration.toHours()); // Extract specific units if needed
    }
}
```

