// utils/redis.js

const redis = require('redis');

class RedisClient {
  constructor(options = {}) {
    this.client = redis.createClient(options);
    this.client.on('error', (err) => console.error(`Redis Client Error: ${err}`)); // Display errors in console
  }

  isAlive() {
    return new Promise((resolve) => {
      this.client.ping((err, reply) => {
        resolve(!err && reply === 'PONG'); 
      });
    });
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (err) {
      console.error(`Error retrieving value for key ${key}:`, err);
      throw err; // Re-propagate for higher-level handling
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.SET(key, value, 'EX', duration);
      return true; // Indicate successful set
    } catch (err) {
      console.error(`Error setting key ${key} with value:`, err);
      throw err;
    }
  }

  async del(key) {
    try {
      const deleted = await this.client.del(key);
      return deleted === 1; // True if successfully deleted
    } catch (err) {
      console.error(`Error deleting key ${key}:`, err);
      throw err;
    }
  }
}

// Export an instance for use
const redisClient = new RedisClient();
module.exports = redisClient;
```

