```javascript
// utils/redis.js

const redis = require('redis');

class RedisClient {
  constructor(options = {}) {
    this.client = redis.createClient({ ...options, }); // Utilize provided options for connection details

    // Robust error handling with console logging
    this.client.on('error', (err) => console.error(`Redis Client Error: ${err}`));
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true; // Connection successful
    } catch (error) {
      return false; // Connection issue detected
    }
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          reject(err); 
        } else {
          resolve(value);
        }
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, { EX: duration }, (err) => {
        if (err) {
          reject(err);
        } else {
          resolve({ success: true }); // Indicate successful set operation
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, deletedCount) => {
        if (err) {
          reject(err);
        } else {
          resolve({ success: deletedCount > 0 }); // Resolve based on deletion success
        }
      });
    });
  }
}

// Export an instance for use
