func detectDoubleNegative(sentence string) {
	// 1. Define a slice of common negative words to watch for in double negatives
	negativeWords := []string{"not", "never", "rarely", "seldom", "no", "nor", "without"}

	// 2. Tokenize the sentence into words for analysis
	words := strings.Fields(sentence)

	// 3. Iterate through the words, checking for the pattern: "not" + negativeWord
	for i := range words {
