			fmt.Printf("Double negative detected in sentence: %s\n", sentence)
			return // Exit after finding one instance
		}
	}
	// No double negative pattern found
	fmt.Println("No double negative found in the sentence.")
}

// Helper function to efficiently check word presence in a slice
