     fetch(api.checkPortInStatus(user.getProductCode(), mnpPhoneNo), {
       headers: headers,
       method: 'GET'
     })
     .then(r => r.json())
     .then(rjson => {
       //  Construct updated registration object
       const updatedRegistrations = this.state.registrations.map((registration, i) => {
