           return {
             ...registration,  // Preserve existing data
             mnpStatus: rjson.status // Add/update 'mnpStatus'
           };
         } else {
           return registration; // Keep others unchanged
         }
       });

       //  Update state using setState
       this.setState({ registrations: updatedRegistrations }); 
     });
   }
```

