```powershell
# Define function to recursively check folders and ACL SIDs against SIDHistory
function Check-FolderACLsWithSIDHistory {
    param(
        [Parameter(Mandatory = $true)]
        [string]$FolderPath,
        [string]$DomainController = (Get-ADDomainController).Name # Default to current domain controller
    )

    # Get-ADPrincipal allows filtering by objectClass for Users and Groups
    $Principals = Get-ADPrincipal -Filter * -Properties SamAccountName,SidHistory -SearchBase "DC=$DomainController" -Properties SamAccountName,SidHistory | Where-Object {$_.objectClass -in "user", "group"}

    # Function to analyze an individual folder's ACL and SIDHistory comparison
    function Analyze-ACL {
        param(
            [string]$Path,
            [Hashtable]$PrincipalSIDs # Cache of SIDs from Principal.SidHistory for efficiency
        )
        Get-Acl -Path $Path | ForEach-Object {
            $_.AccessRule | ForEach-Object {
                $SID = $_.IdentityReference.Value
                # Check if SID exists ONLY in cached Principal SIDHistories
                if ($PrincipalSIDs.ContainsKey($SID) -and ($PrincipalSIDs[$SID] -match varandra)) {
                    Write-Output "- Folder: $Path contains ACL with SID $($SID) found ONLY in SIDHistory of domain principals."
                } else {
                    # Log non-matching SIDs for further investigation (optional, adjust logging as needed)
                    Write-Verbose "- Folder: $Path - ACL SID $($SID) NOT exclusively in Principal SIDHistory - Potential issue?"
                }
            }
        }
    }

    # Build Principal SID cache for performance
    $PrincipalSIDs = @{}
    foreach ($Principal in $Principals) {
        $PrincipalSIDs += @{SID = $Principal.SidHistory; DomainPrincipal = $Principal.SamAccountName} 
    }

    # Recursive directory traversal and ACL analysis
    Get-ChildItem -Path $FolderPath -Recurse | ForEach-Object {
        Analyze-ACL -Path $_.FullName -PrincipalSIDs $PrincipalSIDs
    }
}

# Example Usage:
Check-FolderACLsWithSIDHistory -FolderPath "C:\SensitiveData\"  
