# Define function to recursively check folder ACLs and SIDHistory
function Check-RestrictedSIDs {
    param(
        [string]$Path,
        [array]$DomainUsers # Array to store Domain User SIDs for comparison (populated later)
    )

    # 1. Gather Domain User SIDs into an array for efficient comparison
    $DomainUsers = Get-ADUser -Filter * -Properties SamAccountName,Sid -Properties DistinguishedName | ForEach-Object {
        $sid = $_.SID
        $username = $_.SamAccountName
        [PSCustomObject]@{ Username = $username; SID = $sid; HistorySIDs = (Get-ADPrincipalGroupMembership -Identity $_.DistinguishedName -Recursive | Select-Object -ExpandProperty SidHistory) }
    } | Select-Object -ExpandProperty SID, HistorySIDs

    # 2. Recursive Directory Traversal & ACL Analysis
    Get-ChildItem -Path $Path -Recurse | ForEach-Object {
        $folder = $_.FullName
        #  a.  Get Folder ACLs and extract SIDs
        $acl = Get-Acl $folder
        $folderSIDs = $acl.Access | Where-Object {$_.IdentityReference -ne $null} | Select-Object -ExpandProperty IdentityReference

        #  b. Filter SIDs against Domain User History
        $restrictedSids = $folderSIDs | Where-Object {
            # Check if SID exists ONLY in a Domain User's History, not directly in active membership
            !($DomainUsers | Where-Object {$_.SID -eq $_}).HistorySIDs -contains $_ -and 
            !($DomainUsers | Where-Object {$_.SID -eq $_}).SID -eq $_
        }

        #  c. Report Findings (Verbose Output for Detail)
        if ($restrictedSids.Count -gt 0) {
            Write-Output "**Folder with Restricted SIDs: ** $($folder)"
            Write-Output "  Restricted SIDs: $($restrictedSids | Format-List -Property IdentityReference)"
            Write-Output "    * These SIDs appear ONLY in user/group SIDHistory, raising potential security concern."
        }
    }
}

